.joint-inspector {
   position: absolute;
   top: 0;
   bottom: 0;
   right: 0;
   left: 0;
   overflow: auto;
}

.joint-inspector label {
   display: block;
   margin-top: 5px;
   margin-bottom: 10px;
}
.joint-inspector label:after {
    content: ':';
}
.joint-inspector input,
.joint-inspector textarea {
   width: 200px;
   height: 20px;
   line-height: 20px;
}

.joint-inspector label.with-output {
    float: left;
}

.joint-inspector output {
    float: left;
    margin: 5px 2px 10px 2px;
}

.joint-inspector .units {
    float: left;
    margin: 5px 0 10px 0;
}

.joint-inspector input[type="range"] {
   clear: both;
   display: block;
}

.joint-inspector select {
   display: block;
}

@media screen and (-ms-high-contrast: active), (-ms-high-contrast: none) {
