    }
}

.joint-inspector .group {
    overflow: hidden;
    padding: 0;
    padding-bottom: 10px;
}
.joint-inspector .group.closed {
    height: auto;
    padding-bottom: 0;
}
.joint-inspector .group.empty {
    display: none;
}

/* prevent tabbing into a close group */
.joint-inspector .group.closed .field {
   display: none;
}

.joint-inspector .group > .group-label {
   position: relative;
   padding: 5px 4px;
   margin-top: 0;
   margin-bottom: 0;
   cursor: pointer;
   -webkit-user-select: none;
   -moz-user-select: none;
   -ms-user-select: none;
   user-select: none;
}
.joint-inspector .group > .group-label:before {
   content: '';
   width: 0;
   height: 0;
   display: inline-block;
   margin-left: 2px;
   margin-right: 5px;
   position: relative;
   top: 5px;
}
.joint-inspector .group.closed > .group-label:before {
   top: 2px;
   left: 2px;
}

.link-tools .tool-options {
   display: block;
}

/* Toggle */

.joint-inspector .toggle {
   position: relative;
   width: 97px;
   height: 14px;
}
.joint-inspector .toggle input {
   top: 0;
   right: 0;
   bottom: 0;
   left: 0;
   -ms-filter: "progid:DXImageTransform.Microsoft.Alpha(Opacity=0)";
   filter: alpha(opacity=0);
   -moz-opacity: 0;
   opacity: 0;
   z-index: 100;
   position: absolute;
   width: 100%;
   height: 100%;
   cursor: pointer;
   box-sizing: border-box;
   padding: 0;
   box-shadow: none;
   -webkit-appearance: none;
}
.joint-inspector .toggle span {
   display: block;
   width: 100%;
   height: 100%;
   border-radius: 40px;
   position: relative;
}
.joint-inspector .toggle span:before {
   box-sizing: border-box;
   padding: 0;
   margin: 0;
   content: "";
   position: absolute;
   z-index: -1;
   top: -18px;
   right: -18px;
   bottom: -18px;
   left: -18px;
   border-radius: inherit;
}
.joint-inspector .toggle input:checked + span i {
   right: 0;
}
.joint-inspector .toggle span i {
   display: block;
   height: 100%;
   width: 60%;
   border-radius: inherit;
   position: absolute;
   z-index: 2;
   right: 40%;
   top: 0;
}
.joint-inspector .btn-list-add,
.joint-inspector .btn-list-del {
   cursor: pointer;
